"use client";

import { useRef, useState } from "react";
import { ArrowUpRight, ChevronRight, X } from "lucide-react";
import { BgFolderVector } from "../../assets/icons";
import { Button } from "../ui/button";
import { Card, CardContent } from "../ui/card";
import {
  dashboardActions,
  dashboardResources,
  dashboardTips,
  inspiredDemos,
} from "../../data";

export function DashboardContent() {
  return (
    <div className="mx-auto w-full max-w-6xl space-y-9 px-4 py-6 sm:p-7">
      <section className="grid grid-cols-1 gap-4 md:grid-cols-3">
        {dashboardActions.map((action) => (
          <DashboardActionCard key={action.title} action={action} />
        ))}
      </section>

      <DashboardTips />

      <div className="flex flex-col gap-8 lg:flex-row">
        <ResourcesSection />
        <InspirationList />
      </div>
    </div>
  );
}

function DashboardActionCard({
  action,
}: {
  action: (typeof dashboardActions)[number];
}) {
  const Icon = action.icon;

  return (
    <Card className="gap-8 rounded-2xl py-4 shadow-border ring-0">
      <CardContent className="flex flex-col items-start gap-8">
        <div className="relative flex size-11 items-center justify-center overflow-hidden rounded-lg">
          <img
            src={action.image}
            alt=""
            width={44}
            height={44}
            className="absolute inset-0 size-full object-cover"
          />
          <Icon className="text-primary-foreground relative z-10 size-6" />
        </div>
        <div className="flex w-full flex-col gap-1">
          <p className="font-medium">{action.title}</p>
          <p className="text-muted-foreground text-sm">{action.description}</p>
        </div>
      </CardContent>
    </Card>
  );
}

function DashboardTips() {
  const [visible, setVisible] = useState(true);
  const scrollRef = useRef<HTMLDivElement>(null);

  if (!visible) {
    return null;
  }

  function scrollRight() {
    if (scrollRef.current) {
      scrollRef.current.scrollBy({
        left: scrollRef.current.clientWidth,
        behavior: "smooth",
      });
    }
  }

  return (
    <section className="flex flex-col gap-8">
      <div className="flex items-center justify-between">
        <div className="flex flex-col gap-2">
          <h2 className="text-lg font-semibold">Supademo Tips</h2>
          <p className="text-muted-foreground">
            Drive successful outcomes across multiple departments and
            interactive demos
          </p>
        </div>
        <Button
          variant="outline"
          size="sm"
          onClick={() => setVisible(false)}
          className="bg-card rounded-full border-0 shadow-border"
          aria-label="Close tips"
        >
          Close
          <X />
        </Button>
      </div>

      <div className="relative overflow-hidden">
        <div
          ref={scrollRef}
          className="flex gap-6 overflow-x-auto pb-2 scroll-smooth"
        >
          {dashboardTips.map((tip) => (
            <article
              key={tip.title}
              className="flex w-64 shrink-0 flex-col items-start gap-4"
            >
              <div className="relative h-44 w-64 overflow-hidden rounded-2xl">
                <img
                  src={tip.image}
                  alt=""
                  width={256}
                  height={176}
                  className="size-full object-cover"
                />
              </div>
              <div className="flex w-full flex-col gap-1">
                <h3 className="font-medium">{tip.title}</h3>
                <p className="text-muted-foreground text-sm">
                  {tip.description}
                </p>
              </div>
            </article>
          ))}
        </div>

        <div className="from-background via-background/70 absolute top-0 right-0 h-64 w-36 bg-gradient-to-l to-transparent" />
        <Button
          variant="outline"
          size="icon-lg"
          onClick={scrollRight}
          className="bg-card absolute top-28 right-0 z-10 rounded-full border-0 shadow-border"
          aria-label="Show more tips"
        >
          <ChevronRight className="size-5" />
        </Button>
      </div>
    </section>
  );
}

function ResourcesSection() {
  return (
    <section className="flex flex-1 flex-col items-start gap-8 lg:max-w-lg">
      <h2 className="text-lg font-semibold">Resources</h2>
      <div className="grid w-full grid-cols-2 gap-4">
        {dashboardResources.map((resource) => {
          const Icon = resource.icon;

          return (
            <article
              key={resource.label}
              className="flex flex-col items-start gap-3"
            >
              <div className="bg-muted flex h-32 w-full items-center justify-center overflow-hidden rounded-xl shadow-border">
                <div className="relative flex size-20 items-center justify-center">
                  <BgFolderVector className="absolute inset-0 size-full" />
                  <Icon className="relative z-10 mt-4 size-6" />
                </div>
              </div>
              <h3 className="font-medium">{resource.label}</h3>
            </article>
          );
        })}
      </div>
    </section>
  );
}

function InspirationList() {
  return (
    <section className="flex flex-1 flex-col items-start gap-8">
      <h2 className="text-lg font-semibold">Get Inspired</h2>
      <div className="flex w-full flex-col gap-2">
        {inspiredDemos.map((item) => (
          <article
            key={item.title}
            className="bg-muted flex h-18 w-full items-center justify-between rounded-2xl py-4 pr-8 pl-6 shadow-border"
          >
            <div className="flex items-center gap-4">
              <div className="relative size-10 shrink-0 overflow-hidden">
                <img
                  src={item.image}
                  alt=""
                  width={40}
                  height={40}
                  className="size-full object-cover"
                />
              </div>
              <h3 className="font-medium">{item.title}</h3>
            </div>
            <ArrowUpRight className="text-muted-foreground size-6" />
          </article>
        ))}
      </div>
    </section>
  );
}

"use client";

import { useMemo, useState, type ReactNode } from "react";
import {
  Archive,
  ArrowDownWideNarrow,
  Copy,
  EllipsisVertical,
  ExternalLink,
  Filter,
  FolderInput,
  FolderPlus,
  Grid2X2,
  Info,
  List,
  Pencil,
  Plus,
  Trash2,
  UserRound,
  Users,
} from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "../ui/avatar";
import { Button } from "../ui/button";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "../ui/dropdown-menu";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "../ui/tabs";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "../ui/tooltip";
import {
  sortLabels,
  supademoAuthors,
  supademos,
  type SortMode,
  type Supademo,
  type ViewMode,
} from "../../data";
import { cn } from "../../lib/utils";

export function SupademosContent() {
  const [sort, setSort] = useState<SortMode>("recent");
  const [selectedAuthors, setSelectedAuthors] = useState<string[]>([]);
  const [view, setView] = useState<ViewMode>("grid");

  const visibleSupademos = useMemo(() => {
    const filtered = selectedAuthors.length
      ? supademos.filter((supademo) =>
          selectedAuthors.includes(supademo.author),
        )
      : supademos;

    if (sort === "ascending") {
      return [...filtered].sort((a, b) => a.title.localeCompare(b.title));
    }
    if (sort === "descending") {
      return [...filtered].sort((a, b) => b.title.localeCompare(a.title));
    }
    return filtered;
  }, [selectedAuthors, sort]);

  return (
    <TooltipProvider delay={300}>
      <Tabs defaultValue="supademos" className="min-w-0">
        <main className="w-full min-w-0 px-4 py-6 sm:p-7">
          <div className="flex flex-col gap-5 sm:flex-row sm:items-center sm:justify-between">
            <div className="flex items-center gap-2">
              <h2 className="text-xl font-semibold">Team Supademos</h2>
              <Tooltip>
                <TooltipTrigger
                  render={
                    <Button
                      variant="ghost"
                      size="icon-xs"
                      className="text-muted-foreground rounded-full"
                      aria-label="About Team Supademos"
                    >
                      <Info className="size-4" />
                    </Button>
                  }
                />
                <TooltipContent>
                  Supademos shared with everyone in your workspace
                </TooltipContent>
              </Tooltip>
            </div>

            <div className="flex w-full flex-wrap items-center justify-between gap-3 sm:w-auto sm:flex-nowrap sm:justify-start sm:gap-4">
              <TabsList className="h-10! gap-0 rounded-xl shadow-border">
                <PrimaryTab value="supademos">Supademos</PrimaryTab>
                <PrimaryTab value="screenshots">Screenshots</PrimaryTab>
              </TabsList>
              <DropdownMenu>
                <DropdownMenuTrigger
                  render={
                    <Button size="lg" className="rounded-xl shadow-primary">
                      Create
                      <Plus className="size-5" />
                    </Button>
                  }
                />
                <DropdownMenuContent align="end" className="w-48">
                  <DropdownMenuItem>
                    <Plus />
                    New Supademo
                  </DropdownMenuItem>
                  <DropdownMenuItem>
                    <Plus />
                    New Screenshot
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          </div>

          <TabsContent value="supademos">
            <Tabs
              defaultValue="shared"
              className="mt-8 min-w-0 gap-6 sm:mt-10 sm:gap-8"
            >
              <SupademosToolbar
                sort={sort}
                setSort={setSort}
                selectedAuthors={selectedAuthors}
                setSelectedAuthors={setSelectedAuthors}
                view={view}
                setView={setView}
              />
              <TabsContent value="shared">
                <SupademoCollection demos={visibleSupademos} view={view} />
              </TabsContent>
              <TabsContent value="personal">
                <EmptyState
                  title="No personal Supademos yet"
                  description="Supademos visible only to you will appear here."
                />
              </TabsContent>
              <TabsContent value="archive">
                <EmptyState
                  title="Archive is empty"
                  description="Archived Supademos will appear here."
                />
              </TabsContent>
            </Tabs>
          </TabsContent>
          <TabsContent value="screenshots">
            <EmptyState
              title="No screenshots yet"
              description="Create a screenshot to see it in this workspace."
              className="mt-10"
            />
          </TabsContent>
        </main>
      </Tabs>
    </TooltipProvider>
  );
}

function PrimaryTab({
  value,
  children,
}: {
  value: string;
  children: ReactNode;
}) {
  return (
    <TabsTrigger
      value={value}
      className="data-active:bg-primary/10 data-active:text-primary flex-none rounded-lg px-3 data-active:shadow-none!"
    >
      {children}
    </TabsTrigger>
  );
}

type SupademosToolbarProps = {
  sort: SortMode;
  setSort: (sort: SortMode) => void;
  selectedAuthors: string[];
  setSelectedAuthors: (authors: string[]) => void;
  view: ViewMode;
  setView: (view: ViewMode) => void;
};

function SupademosToolbar({
  sort,
  setSort,
  selectedAuthors,
  setSelectedAuthors,
  view,
  setView,
}: SupademosToolbarProps) {
  function toggleAuthor(author: string, checked: boolean) {
    setSelectedAuthors(
      checked
        ? [...selectedAuthors, author]
        : selectedAuthors.filter((item) => item !== author),
    );
  }

  return (
    <div className="flex min-w-0 flex-col gap-4 border-b lg:flex-row lg:items-end lg:justify-between">
      <TabsList variant="line">
        <WorkspaceTab value="shared" icon={Users}>
          <span className="sm:hidden">Team</span>
          <span className="hidden sm:inline">Shared with Team</span>
        </WorkspaceTab>
        <WorkspaceTab value="personal" icon={UserRound}>
          Personal
        </WorkspaceTab>
        <WorkspaceTab value="archive" icon={Archive}>
          Archive
        </WorkspaceTab>
      </TabsList>

      <div className="flex w-full flex-wrap items-center gap-2 pb-3 lg:w-auto lg:gap-3 lg:pb-2">
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button
                variant="outline"
                size="lg"
                className="bg-card text-muted-foreground mr-auto rounded-xl border-0 shadow-border"
              >
                <ArrowDownWideNarrow className="size-5" />
                {sortLabels[sort]}
              </Button>
            }
          />
          <DropdownMenuContent align="end" className="w-48">
            <DropdownMenuRadioGroup
              value={sort}
              onValueChange={(value) => setSort(value as SortMode)}
            >
              <DropdownMenuLabel>Sort by</DropdownMenuLabel>
              {Object.entries(sortLabels).map(([value, label]) => (
                <DropdownMenuRadioItem key={value} value={value}>
                  {label}
                </DropdownMenuRadioItem>
              ))}
            </DropdownMenuRadioGroup>
          </DropdownMenuContent>
        </DropdownMenu>

        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button
                variant="outline"
                size="lg"
                className={cn(
                  "bg-card text-muted-foreground rounded-xl border-0 shadow-border",
                  selectedAuthors.length && "bg-muted",
                )}
                aria-label="Filter by creator"
              >
                <Filter className="size-5" />
                <span className="hidden sm:inline">Filter</span>
                {selectedAuthors.length > 0 && (
                  <span className="bg-primary text-primary-foreground flex size-5 items-center justify-center rounded-full text-xs">
                    {selectedAuthors.length}
                  </span>
                )}
              </Button>
            }
          />
          <DropdownMenuContent align="end" className="w-52">
            <DropdownMenuGroup>
              <DropdownMenuLabel>Filter by creator</DropdownMenuLabel>
              {supademoAuthors.map((author) => (
                <DropdownMenuCheckboxItem
                  key={author}
                  checked={selectedAuthors.includes(author)}
                  onCheckedChange={(checked) => toggleAuthor(author, checked)}
                >
                  {author}
                </DropdownMenuCheckboxItem>
              ))}
            </DropdownMenuGroup>
            {selectedAuthors.length > 0 && (
              <>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => setSelectedAuthors([])}>
                  Clear filters
                </DropdownMenuItem>
              </>
            )}
          </DropdownMenuContent>
        </DropdownMenu>

        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button
                variant="outline"
                size="icon-lg"
                className="bg-card text-muted-foreground rounded-xl border-0 shadow-border"
                aria-label="Folder options"
              >
                <FolderPlus className="size-5" />
              </Button>
            }
          />
          <DropdownMenuContent align="end" className="w-44">
            <DropdownMenuItem>
              <FolderPlus />
              New folder
            </DropdownMenuItem>
            <DropdownMenuItem>
              <FolderInput />
              Manage folders
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>

        <Button
          variant="outline"
          size="icon-lg"
          className={cn(
            "bg-card text-muted-foreground rounded-xl border-0 shadow-border",
            view === "list" && "bg-muted",
          )}
          aria-label={view === "grid" ? "Use list view" : "Use grid view"}
          onClick={() => setView(view === "grid" ? "list" : "grid")}
        >
          {view === "grid" ? (
            <List className="size-5" />
          ) : (
            <Grid2X2 className="size-5" />
          )}
        </Button>
      </div>
    </div>
  );
}

function WorkspaceTab({
  value,
  icon: Icon,
  children,
}: {
  value: string;
  icon: typeof Users;
  children: ReactNode;
}) {
  return (
    <TabsTrigger
      value={value}
      className="data-active:text-primary data-active:after:bg-primary px-2 text-sm sm:px-4 sm:text-base"
    >
      <Icon className="size-4 sm:size-5" />
      {children}
    </TabsTrigger>
  );
}

function SupademoCollection({
  demos,
  view,
}: {
  demos: Supademo[];
  view: ViewMode;
}) {
  if (!demos.length) {
    return (
      <EmptyState
        title="No matching Supademos"
        description="Clear or change the active creator filters."
      />
    );
  }

  return (
    <section
      className={cn(
        view === "grid"
          ? "grid grid-cols-1 gap-6 sm:grid-cols-2 xl:grid-cols-4"
          : "space-y-3",
      )}
    >
      {demos.map((supademo) => (
        <article
          key={supademo.id}
          className={cn(
            "group min-w-0 cursor-pointer",
            view === "list" &&
              "hover:bg-muted/40 flex w-full max-w-full items-center gap-3 overflow-hidden rounded-2xl border p-3 transition sm:gap-4",
          )}
        >
          <div
            className={cn(
              "relative aspect-video overflow-hidden rounded-2xl border",
              view === "list" && "w-2/5 max-w-44 shrink-0",
            )}
          >
            <img
              src={supademo.image}
              alt=""
              width={1280}
              height={720}
              className="size-full object-cover motion-safe:transition-transform motion-safe:duration-300 motion-safe:group-hover:scale-105"
            />
          </div>

          <div
            className={cn(
              "min-w-0 space-y-2",
              view === "grid" ? "mt-4" : "flex-1",
            )}
          >
            <div className="flex items-center justify-between gap-3">
              <div className="min-w-0 flex-1">
                <h3 className="truncate font-medium transition-colors group-hover:text-primary">
                  {supademo.title}
                </h3>
              </div>
              <CardMenu title={supademo.title} />
            </div>
            <div className="text-muted-foreground flex min-w-0 items-center gap-2 text-xs">
              <Avatar size="sm" className="shrink-0">
                <AvatarImage src={supademo.avatar} alt={supademo.author} />
                <AvatarFallback>{supademo.initials}</AvatarFallback>
              </Avatar>
              <span className="truncate">{supademo.author}</span>
              <span aria-hidden>·</span>
              <time className="shrink-0" dateTime="2026-03-02">
                Mar 02
              </time>
            </div>
          </div>
        </article>
      ))}
    </section>
  );
}

function CardMenu({ title }: { title: string }) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            variant="ghost"
            size="icon-xs"
            className="text-muted-foreground rounded-full"
            aria-label={`More options for ${title}`}
          >
            <EllipsisVertical className="size-4" />
          </Button>
        }
      />
      <DropdownMenuContent align="end" className="w-44">
        <DropdownMenuItem>
          <ExternalLink />
          Open
        </DropdownMenuItem>
        <DropdownMenuItem>
          <Pencil />
          Rename
        </DropdownMenuItem>
        <DropdownMenuItem>
          <Copy />
          Duplicate
        </DropdownMenuItem>
        <DropdownMenuItem>
          <FolderInput />
          Move to folder
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem>
          <Archive />
          Archive
        </DropdownMenuItem>
        <DropdownMenuItem variant="destructive">
          <Trash2 />
          Delete
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function EmptyState({
  title,
  description,
  className,
}: {
  title: string;
  description: string;
  className?: string;
}) {
  return (
    <div
      className={cn(
        "bg-muted/40 flex min-h-64 flex-col items-center justify-center gap-2 rounded-2xl border border-dashed px-6 text-center",
        className,
      )}
    >
      <p className="font-medium">{title}</p>
      <p className="text-muted-foreground text-sm">{description}</p>
    </div>
  );
}

"use client";

import { useState } from "react";
import {
  Blocks,
  ChevronDown,
  ChevronsLeft,
  LogOut,
  Moon,
  Settings,
  Sun,
  User,
} from "lucide-react";
import { useTheme } from "next-themes";
import { BuildingIcon, CaretUpDownIcon } from "../../assets/icons";
import { supademoLogo } from "../../assets/images";
import { SidebarNavigationItem } from "./sidebar-navigation-item";
import { Avatar, AvatarFallback, AvatarImage } from "../ui/avatar";
import { Button } from "../ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "../ui/dropdown-menu";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
  SidebarMenu,
  useSidebar,
} from "../ui/sidebar";
import {
  adminNavigation,
  companies,
  workspaceNavigation,
} from "../../navigation-data";
import { cn } from "../../lib/utils";

export function AppSidebar() {
  const { isMobile, setOpen, setOpenMobile, state } = useSidebar();
  const { resolvedTheme, setTheme } = useTheme();
  const collapsed = !isMobile && state === "collapsed";
  const [membersOpen, setMembersOpen] = useState(false);
  const [selectedCompany, setSelectedCompany] = useState<
    (typeof companies)[number]
  >(companies[0]);

  return (
    <Sidebar
      collapsible="icon"
      className="m-1.5 h-[calc(100svh-0.75rem)]! w-[calc(var(--sidebar-width)-0.75rem)]! border-none! group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)-0.75rem)]! [&>[data-sidebar=sidebar]]:bg-transparent"
    >
      <SidebarHeader className="p-0">
        <div
          className={cn(
            "bg-card flex shrink-0 flex-col rounded-2xl border shadow-border",
            collapsed ? "items-center py-2" : "p-3 pt-3.5",
          )}
        >
          <div
            className={cn(
              "flex w-full items-center",
              collapsed ? "justify-center" : "justify-between",
            )}
          >
            {collapsed ? (
              <div className="group/logo relative flex size-10 shrink-0 items-center justify-center">
                <img
                  src={supademoLogo}
                  alt="Supademo"
                  width={32}
                  height={32}
                  className="size-8 shrink-0 transition-opacity duration-200 group-hover/logo:opacity-0"
                />
                <Button
                  aria-label="Expand sidebar"
                  variant="ghost"
                  size="icon-lg"
                  className="pointer-events-none absolute rounded-full opacity-0 transition-opacity duration-200 group-hover/logo:pointer-events-auto group-hover/logo:opacity-100 focus-visible:pointer-events-auto focus-visible:opacity-100"
                  onClick={() => setOpen(true)}
                >
                  <ChevronsLeft className="size-5 rotate-180" />
                </Button>
              </div>
            ) : (
              <div className="flex items-center gap-2">
                <img
                  src={supademoLogo}
                  alt=""
                  width={28}
                  height={28}
                  className="size-7"
                />
                <span className="text-lg font-semibold">Supademo</span>
              </div>
            )}
            {!collapsed && (
              <Button
                aria-label={isMobile ? "Close sidebar" : "Collapse sidebar"}
                variant="ghost"
                size="icon-lg"
                className="rounded-full"
                onClick={() =>
                  isMobile ? setOpenMobile(false) : setOpen(false)
                }
              >
                <ChevronsLeft className="size-5" />
              </Button>
